const { handleIncomingMessage } = require('../../modules/ai/handleIncomingMessage');
const { fallbackResponse } = require('../../modules/ai/fallback');
const sendWhatsApp = require('../../services/whatsapp.unified');

console.log('🚀 AFRI QUEUE ENGINE v2 (FAULT-TOLERANT MODE)');

const queue = [];
let processing = false;

function normalize(job) {
  return {
    from: job?.from || 'unknown',
    message: job?.message || ''
  };
}

async function safeAI(job) {
  try {
    const res = await handleIncomingMessage(job);
    if (!res || typeof res !== 'object') throw new Error('Invalid AI response');
    if (!res.reply) throw new Error('Missing reply field');
    return res;
  } catch (e) {
    console.log('⚠️ AI FAILED → fallback activated:', e.message);
    return await fallbackResponse(job);
  }
}

async function processQueue() {
  if (processing) return;
  processing = true;

  while (queue.length > 0) {
    const job = normalize(queue.shift());

    try {
      const aiResponse = await safeAI(job);

      await sendWhatsApp({
        to: job.from,
        message: aiResponse.reply || '🛠 No response generated'
      });

    } catch (err) {
      console.log('❌ QUEUE CRASH BLOCKED:', err.message);
    }
  }

  processing = false;
}

function enqueue(job) {
  queue.push(job);
  processQueue();
}

module.exports = {
  enqueue,
  processQueue
};
